/// <summary>
/// Extension of the method <m>init</m>
/// </summary>
public void init()
{
    next init();
    AVAKoRe bec_KoRe = LedgerParameters::find().AVAKoRe;
    this.design().controlName(formControlStr(LedgerAllocationRule, AVASequence)).visible(bec_KoRe);
    this.design().controlName(formControlStr(LedgerAllocationRule, LedgerAllocationRule_AVACostAllocationJournal)).visible(bec_KoRe);
    this.dataSource(formDataSourceStr(LedgerAllocationRule, LedgerAllocationRule)).object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).visible(bec_KoRe);
    this.dataSource(formDataSourceStr(LedgerAllocationRule, LedgerAllocationRule)).object(fieldNum(LedgerAllocationRule, AVAAutomaticHeadcountUpdate)).visible(bec_KoRe);

    LedgerAllocationRule_ds.object(fieldNum(LedgerAllocationRule, AVADestinationFromDimensionValue)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(LedgerAllocationRule, AVAOverrideDimValueLookup), this);
    LedgerAllocationRule_ds.object(fieldNum(LedgerAllocationRule, AVADestinationToDimensionValue)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(LedgerAllocationRule, AVAOverrideDimValueLookup), this);
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_formCtrl">FormStringControl</param>
public void AVAOverrideDimValueLookup(FormStringControl _formCtrl)
{
    FormStringControl   dimNameCtrl;
    Name                dimName;
    DimensionAttribute  dimensionAttribute;
    dimNameCtrl = this.control(this.controlId(formControlStr(LedgerAllocationRule, LedgerAllocationRule_AVADestinationDimAttributeName)));
    dimName = dimNameCtrl.valueStr();
    dimensionAttribute = DimensionAttribute::findByName(dimName);
    DimensionValueLookupHelper::lookupDimensionValues(dimensionAttribute, _formCtrl);

}
